#include <bits/stdc++.h>
using namespace std;

class Arc {
public:
  int source, destination;
  double weight;
  Arc(int s, int d, double w) : source(s), destination(d), weight(w) {}
};

class Node {
public:
  vector<int> outgoing;
};

class Network {
public:
  vector<Node> nodes;
  vector<Arc> arcs;

  Network(int v, int e) : nodes(v), arcs() {
    arcs.reserve(e);
  }

  void connect(int from, int to, double cap) {
    arcs.emplace_back(from, to, cap);
    nodes[from].outgoing.push_back(arcs.size() - 1);
  }

  vector<int> augmenting_path(int src, int dst, vector<double>& flow, double* cap) {
    using PQ = set<pair<double,int>, greater<pair<double,int>>>;
    PQ pq;
    vector<double> best_cap(nodes.size(), 0.0);
    vector<int> pred(nodes.size(), -1);

    best_cap[src] = numeric_limits<double>::infinity();
    pq.insert({best_cap[src], src});

    while (!pq.empty() && best_cap[dst] == 0) {
      auto it = pq.begin();
      double c = it->first;
      int u = it->second;
      pq.erase(it);

      for (int idx : nodes[u].outgoing) {
        const Arc& a = arcs[idx];
        double res = a.weight - flow[idx];
        if (res > 0) {
          double nc = min(c, res);
          if (nc > best_cap[a.destination]) {
            auto pit = pq.find({best_cap[a.destination], a.destination});
            if (pit != pq.end()) pq.erase(pit);
            best_cap[a.destination] = nc;
            pq.insert({best_cap[a.destination], a.destination});
            pred[a.destination] = idx;
          }
        }
      }
    }

    *cap = best_cap[dst];
    vector<int> path;
    for (int i = pred[dst]; i != -1; i = pred[arcs[i].source])
      path.push_back(i);
    return path;
  }

  double maximize_flow(int s, int t) {
    Network residual(nodes.size(), 2 * arcs.size());
    vector<double> f(2 * arcs.size(), 0.0);

    for (size_t i = 0; i < arcs.size(); ++i) {
      residual.connect(arcs[i].source, arcs[i].destination, arcs[i].weight);
      residual.connect(arcs[i].destination, arcs[i].source, 0.0);
    }

    double total = 0.0;
    double cap;
    for (auto path = residual.augmenting_path(s, t, f, &cap);
         !path.empty() && cap > 0;
         path = residual.augmenting_path(s, t, f, &cap)) {
      for (int e : path) {
        int rev = (e & 1) ? e - 1 : e + 1;
        f[e] += cap;
        f[rev] -= cap;
      }
      total += cap;
    }

    for (int idx : residual.nodes[s].outgoing)
      total += f[idx];
    return total;
  }
};

int N, T;
struct Tile {
  int x, y;
  bitset<61> contaminated;
  bitset<61> traversable;
  int agents{}, capsules{};

  Tile() : agents(0), capsules(0) { traversable.set(); }

  int encode(int step) const { return 2 + x + N*y + N*N*step; }

  void isolate() { traversable.reset(); }

  void contagion(int step = 0) {
    if (traversable.test(step)) {
      traversable.reset(step);
      contaminated.set(step);
    }
  }

  void propagate(int step);
};

Tile board[10][10];

void Tile::propagate(int step) {
  if (contaminated.test(step)) {
    contagion(step + 1);
    if (x > 0) board[x-1][y].contagion(step + 1);
    if (x < N - 1) board[x+1][y].contagion(step + 1);
    if (y > 0) board[x][y-1].contagion(step + 1);
    if (y < N - 1) board[x][y+1].contagion(step + 1);
  }
}

string node_name(int id) {
  if (id == 0) return "source";
  if (id == 1) return "sink";
  ostringstream out;
  int r = (id - 2) % N;
  int c = ((id - 2 - r) % (N*N)) / N;
  int t = (id - 2 - r - c*N) / (N*N);
  out << "(" << r << "," << c << "," << t << ")";
  return out.str();
}

int main() {
  ios::sync_with_stdio(false);
  cin >> N >> T;

  for (int i = 0; i < N; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < N; ++j) {
      board[i][j].x = i;
      board[i][j].y = j;
      if (line[j] == 'Y') board[i][j].isolate();
      else if (line[j] == 'Z') board[i][j].contagion();
      else board[i][j].agents = line[j] - '0';
    }
  }

  for (int i = 0; i < N; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < N; ++j) {
      if (line[j] != 'Y' && line[j] != 'Z')
        board[i][j].capsules = line[j] - '0';
    }
  }

  for (int step = 0; step <= T; ++step)
    for (int i = 0; i < N; ++i)
      for (int j = 0; j < N; ++j)
        if (step < T) board[i][j].propagate(step);

  Network net(N*N*(T+1)+2, 100*4*60);
  for (int i = 0; i < N; ++i)
    for (int j = 0; j < N; ++j) {
      const Tile& t = board[i][j];
      if (t.agents) net.connect(0, t.encode(0), t.agents);
      if (t.capsules) net.connect(t.encode(T), 1, t.capsules);
      for (int step = 0; step < T; ++step) {
        if (t.capsules) net.connect(t.encode(step), t.encode(T), 1000);
        if (t.traversable.test(step)) {
          if (i > 0 && board[i-1][j].traversable.test(step))
            net.connect(t.encode(step), board[i-1][j].encode(step+1), 1000);
          if (i < N-1 && board[i+1][j].traversable.test(step))
            net.connect(t.encode(step), board[i+1][j].encode(step+1), 1000);
          if (j > 0 && board[i][j-1].traversable.test(step))
            net.connect(t.encode(step), board[i][j-1].encode(step+1), 1000);
          if (j < N-1 && board[i][j+1].traversable.test(step))
            net.connect(t.encode(step), board[i][j+1].encode(step+1), 1000);
        }
      }
    }

  cout << int(net.maximize_flow(0, 1)) << '\n';
  return 0;
}
